tasks.solution:
function cache_key(string $resource, int $version, array $parts): string
{
    sort($parts, SORT_STRING);

    $key = 'cache:' . $resource . ':v' . $version;

    foreach ($parts as $part) {
        $key .= ':' . $part;
    }

    return $key;
}

tasks.test_suite:
expect('hit without lock: never recompute', should_recompute(true, false), false);
expect('hit with lock: still never recompute', should_recompute(true, true), false);
expect('miss without lock: wait, do not recompute', should_recompute(false, false), false);
expect('miss with lock: owner recomputes once', should_recompute(false, true), true);
